INSERT INTO exams (title,code,duration_minutes,total_marks,passing_marks,active) VALUES ('Java Programming Examination','JAVA-15',20,15,9,1);
INSERT INTO exams (title,code,duration_minutes,total_marks,passing_marks,active) VALUES ('Data Structures & Algorithms Examination','DSA-15',20,15,9,1);
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which of the following is the correct signature of the main method that the JVM invokes?','b',1,'The JVM looks for `public static void main(String[] args)` — public so it is reachable, static so no object is needed, and void because it returns nothing.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'What is the size of the Java `int` primitive data type?','b',1,'`int` is always 32 bits in Java. Unlike C/C++, primitive sizes are fixed by the specification, which is why Java is platform-independent.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which keyword is used to declare a variable whose value cannot be changed after assignment?','b',1,'`final int MAX = 100;` makes the variable a constant. `const` is a reserved but unused keyword in Java.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'What is the value of the expression `10 % 3` in Java?','b',1,'The `%` (modulus) operator returns the remainder: 10 divided by 3 leaves a remainder of 1.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which statement is best suited for checking a variable against many constant values in a single construct?','b',1,'A `switch` selects one branch among several constant cases and is cleaner and faster than a long if-else chain.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'How many times does the body of `for (int i = 0; i < 5; i++)` execute?','b',1,'i takes values 0, 1, 2, 3, 4 — that is five iterations. The loop stops when i == 5.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'What is the default value of each element in a newly created `int[]` array in Java?','b',1,'Array elements are always initialised to the type''s default — 0 for int, false for boolean, null for objects.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which method should be used to compare the contents of two String objects?','b',1,'`==` compares object references, whereas `equals()` on String is overridden to compare the actual character content.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which of the following is NOT one of the four pillars of object-oriented programming?','c',1,'The four pillars are encapsulation, inheritance, polymorphism and abstraction. Compilation is a build step, not an OOP principle.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which keyword is used by a subclass to inherit from a superclass in Java?','b',1,'Classes use `extends` for inheritance; `implements` is used for interfaces, and `super` refers to the parent implementation.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Method overriding in Java is an example of which type of polymorphism?','b',1,'Overriding is resolved at runtime by dynamic method dispatch based on the actual object type. Overloading is compile-time polymorphism.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'What is the standard Java technique for achieving encapsulation?','b',1,'Hiding state behind private fields and controlling access via accessors protects invariants and hides implementation details.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which keyword is used to declare a method that has no body and must be implemented by a subclass?','b',1,'An `abstract` method has no body; the containing class must also be abstract and concrete subclasses must implement it.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which block always executes regardless of whether an exception was thrown in the try block?','b',1,'`finally` runs for normal completion, for a `return`, and also when an exception propagates — ideal for releasing resources.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which collection class allows duplicate elements and gives constant-time access by index?','b',1,'`ArrayList` is a growable array: it permits duplicates, preserves insertion order and offers O(1) indexed access. `HashSet` forbids duplicates.' FROM exams WHERE code='JAVA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'What is the time complexity of accessing an element by index in an array?','a',1,'Elements are contiguous, so address arithmetic (base + index × size) finds any element in constant time.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which technique finds the middle of a singly linked list in a single traversal?','b',1,'Advance one pointer by one node and another by two; when the fast pointer reaches the end, the slow pointer is at the middle.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'A stack follows which order of element access?','b',1,'A stack pushes and pops at the same end (the top), so the most recently inserted element leaves first.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'A queue processes elements in which order?','b',1,'A queue inserts at the rear and removes from the front, giving First In First Out behaviour.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'How many edges does a tree with n nodes contain?','b',1,'Every node except the root has exactly one incoming edge, so a tree with n nodes has n - 1 edges.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which traversal of a Binary Search Tree yields keys in ascending sorted order?','c',1,'In-order traversal (left, root, right) visits a BST''s keys in non-decreasing order.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which data structure is used to implement Breadth-First Search (BFS)?','b',1,'BFS explores level by level and stores the frontier in a FIFO queue. DFS uses a stack instead.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which sorting algorithm guarantees O(n log n) time in the worst case and is stable?','b',1,'Merge Sort always divides the array in half — O(n log n) worst case — and preserves the relative order of equal keys.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'What is the mandatory precondition for applying binary search?','b',1,'Binary search discards half the search space each step, which is only valid when the data is ordered.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'What is the purpose of a base case in a recursive function?','b',1,'Without a base case the function calls itself forever until the call stack overflows. The base case is the stopping condition.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'What is the worst-case time complexity of binary search on a sorted array of n elements?','b',1,'Each comparison halves the remaining search space, so at most log₂n comparisons are needed.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'A recursive algorithm of depth n without memoisation uses additional space in which structure?','b',1,'Each pending call keeps a stack frame, so the auxiliary space is O(n) for depth n. Deep recursion risks StackOverflowError.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which technique resolves hash collisions by storing colliding entries in a list at the same bucket?','b',1,'Separate chaining keeps a linked list (or tree) per bucket, which is how java.util.HashMap stores colliding keys.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which two properties make a problem suitable for dynamic programming?','b',1,'DP applies when subproblems repeat (so results can be cached) and an optimal solution is built from optimal sub-solutions.' FROM exams WHERE code='DSA-15';
INSERT INTO questions (exam_id,question_text,correct_option,marks,explanation) SELECT id,'Which of the following is a NON-LINEAR data structure?','d',1,'Trees and graphs are non-linear: an element may be connected to many others. Arrays, lists, stacks and queues are linear.' FROM exams WHERE code='DSA-15';
